import { SocialsEditor } from '@/components/socials-editor';
import { find, mount, texts } from '@/tests/client-hooks';
import { done, is } from '@/tests/check';
type N = { type?: unknown; props: any };
const node = (tree: unknown, id: string) => find(tree, n => n.props?.id === id)[0] as N;
const open = (tree: unknown) => find(tree, n => n.type === 'button' && texts(n.props?.children).join('').includes('your profiles'))[0] as N;
async function main() {
  const a = await mount(SocialsEditor, { socials: [] });
  open(a.tree()).props.onClick(); await a.settle();
  const before = node(a.tree(), 'social-0-value');
  before.props.onChange({ target: { value: 'https://marktmorgen.com' } }); await a.settle();
  is('the real input handler selects Website', node(a.tree(), 'social-0-network').props.value, 'website');
  is('input identity and typed value survive selection', [node(a.tree(), 'social-0-value').props.id, node(a.tree(), 'social-0-value').props.value], [before.props.id, 'https://marktmorgen.com']);
  is('valid site has no invalid state', node(a.tree(), 'social-0-value').props['aria-invalid'], undefined);
  is('description names the linked address', texts(node(a.tree(), 'social-0-note')).join(''), 'Opens marktmorgen.com');
  is('description remains tied to the same field', node(a.tree(), 'social-0-value').props['aria-describedby'], 'social-0-note');
  a.unmount();

  const b = await mount(SocialsEditor, { socials: [{ network: 'website' as const, url: 'https://first.example' }, { network: 'instagram' as const, url: 'https://www.instagram.com/synthetic' }] });
  open(b.tree()).props.onClick(); await b.settle();
  node(b.tree(), 'social-1-value').props.onChange({ target: { value: 'https://second.example' } }); await b.settle();
  is('an existing Website row prevents a second automatic Website', node(b.tree(), 'social-1-network').props.value, 'instagram');
  is('the existing Website is preserved', node(b.tree(), 'social-0-value').props.value, 'https://first.example');
  is('the other row exposes its error', node(b.tree(), 'social-1-value').props['aria-invalid'], true);
  is('the error uses the corrected wording', texts(node(b.tree(), 'social-1-note')).join(''), 'This is not a handle or an address on Instagram. Only addresses on Instagram itself are linked.');
  node(b.tree(), 'social-1-value').props.onChange({ target: { value: 'https://www.tiktok.com/@synthetic' } }); await b.settle();
  is('a known network still switches through the input handler', node(b.tree(), 'social-1-network').props.value, 'tiktok');
  is('the switched known-network link is valid', node(b.tree(), 'social-1-value').props['aria-invalid'], undefined);
  b.unmount();
  done();
}
void main();

